/** Verifies the native RDF4J transport used by Workbench, rather than SPARQL text substitution. */
class WorkbenchNativeBindingTransportTest {

	private final BlockingQueue<Map<String, String>> requests = new LinkedBlockingQueue<>();
	private HttpServer endpoint;
	private RemoteRepositoryManager manager;
	private Repository repository;

	@BeforeEach
	void setUp() throws IOException {
		endpoint = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		endpoint.createContext("/protocol", exchange -> respond(exchange, "text/plain", Protocol.VERSION));
		endpoint.createContext("/repositories/native", this::operation);
		endpoint.start();
		manager = new RemoteRepositoryManager("http://127.0.0.1:" + endpoint.getAddress().getPort()) {
			@Override
			public boolean hasRepositoryConfig(String repositoryID) {
				// Isolate repository discovery; keep the real manager's repository construction and HTTP session.
				return "native".equals(repositoryID);
			}
		};
		manager.init();
		repository = manager.getRepository("native");
		assertThat(repository).isInstanceOf(HTTPRepository.class);
	}

	@AfterEach
	void tearDown() {
		try {
			if (manager != null) {
				manager.shutDown();
			}
		} finally {
			if (endpoint != null) {
				endpoint.stop(0);
			}
		}
	}

	@Test
	void explorePreservesQueryAndNativeBindingsThroughRepositoryWrappers() throws Exception {
		Value resource = repository.getValueFactory().createBNode("stored-node");
		for (Repository target : List.of(repository, new RepositoryWrapper(repository))) {
			for (boolean count : List.of(false, true)) {
				ExploreQuery spec = ExploreQuery.create(ExploreQuery.Section.OUTGOING, count, "default", 10,
						true, resource, null, repository.getValueFactory());
				RepositoryConnection capture = mock(RepositoryConnection.class);
				when(capture.prepareTupleQuery(anyString())).thenReturn(mock(TupleQuery.class));
				spec.prepare(capture, 5);
				ArgumentCaptor<String> text = ArgumentCaptor.forClass(String.class);
				verify(capture).prepareTupleQuery(text.capture());
				try (RepositoryConnection connection = target.getConnection();
						var result = spec.prepare(connection, 5).evaluate()) {
					assertThat(result.hasNext()).isFalse();
				}
				assertTransport("query", text.getValue(), "subject", resource);
			}
		}
	}

	@Test
	void everyNativeOperationPreservesTextAndBlankNodeBindings() throws Exception {
		Value resource = repository.getValueFactory().createBNode("stored-node");
		try (RepositoryConnection connection = repository.getConnection()) {
			String tupleText = "SELECT (COUNT(DISTINCT *) AS ?count) WHERE { ?s ?p ?o }";
			TupleQuery tuple = connection.prepareTupleQuery(QueryLanguage.SPARQL, tupleText);
			tuple.setBinding("s", resource);
			try (var result = tuple.evaluate()) {
				assertThat(result.hasNext()).isFalse();
			}
			assertTransport("query", tupleText, "s", resource);
			tuple.evaluate(new AbstractTupleQueryResultHandler() {
			});
			assertTransport("query", tupleText, "s", resource);

			String booleanText = "ASK { ?s ?p ?o }";
			BooleanQuery bool = connection.prepareBooleanQuery(QueryLanguage.SPARQL, booleanText);
			bool.setBinding("s", resource);
			assertThat(bool.evaluate()).isTrue();
			assertTransport("query", booleanText, "s", resource);

			String graphText = "CONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o }";
			GraphQuery graph = connection.prepareGraphQuery(QueryLanguage.SPARQL, graphText);
			graph.setBinding("s", resource);
			try (var result = graph.evaluate()) {
				assertThat(result.hasNext()).isFalse();
			}
			assertTransport("query", graphText, "s", resource);
			graph.evaluate(new AbstractRDFHandler() {
			});
			assertTransport("query", graphText, "s", resource);

			String updateText = "DELETE { ?s ?p ?o } WHERE { ?s ?p ?o }";
			Update update = connection.prepareUpdate(QueryLanguage.SPARQL, updateText);
			update.setBinding("s", resource);
			update.execute();
			assertTransport("update", updateText, "s", resource);
		}
	}

	private void assertTransport(String operation, String text, String binding, Value value) {
		Map<String, String> request = requests.poll();
		assertThat(request).isNotNull()
				.containsEntry(operation, text)
				.containsEntry(Protocol.BINDING_PREFIX + binding, Protocol.encodeValue(value));
		assertThat(request.keySet().stream().filter(key -> key.startsWith(Protocol.BINDING_PREFIX)))
				.containsExactly(Protocol.BINDING_PREFIX + binding);
		assertThat(requests).isEmpty();
	}

	private void operation(HttpExchange exchange) throws IOException {
		String parameters = exchange.getRequestURI().getRawQuery();
		if (parameters == null) {
			parameters = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
		}
		Map<String, String> request = new LinkedHashMap<>();
		for (String parameter : parameters.split("&")) {
			String[] pair = parameter.split("=", 2);
			if (pair.length == 2) {
				request.put(URLDecoder.decode(pair[0], StandardCharsets.UTF_8),
						URLDecoder.decode(pair[1], StandardCharsets.UTF_8));
			}
		}
		requests.add(request);
		if (request.containsKey("update")) {
			try (exchange) {
				exchange.sendResponseHeaders(204, -1);
			}
		} else if (request.getOrDefault("query", "").startsWith("ASK")) {
			respond(exchange, "application/sparql-results+json", "{\"head\":{},\"boolean\":true}");
		} else if (request.getOrDefault("query", "").startsWith("CONSTRUCT")) {
			respond(exchange, "text/turtle", "# Empty graph\n");
		} else {
			respond(exchange, "application/sparql-results+json",
					"{\"head\":{\"vars\":[]},\"results\":{\"bindings\":[]}}");
		}
	}

	private static void respond(HttpExchange exchange, String contentType, String body) throws IOException {
		try (exchange) {
			byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
			exchange.getResponseHeaders().set("Content-Type", contentType);
			exchange.sendResponseHeaders(200, bytes.length);
			exchange.getResponseBody().write(bytes);
		}
	}
}
